arguments.command:
cat > .git/hooks/pre-commit <<'EOF'
#!/bin/sh
# Run mypy on all src Python files before commit
mypy src || {
  echo "Type checking failed. Commit aborted." >&2
  exit 1
}
exit 0
EOF
chmod +x .git/hooks/pre-commit

